import os


def load(path, default=None):
    """Читает файл."""
    if not os.path.exists(path):
        return default or {}
    with open(path, encoding="utf-8") as f:
        data = [line.strip() for line in f if line]
    items = {"a": [1, 2], "b": (3, 4)}
    print(f"Строк: {len(data)}", items['a'])
    return data


